import React, { createContext, useContext, useState, useCallback } from 'react';
import { PaginationMeta } from '@/lib/data-table/types';

interface PaginationContextType {
  pageIndex: number;
  pageSize: number;
  pageCount: number;
  totalData: number;
  paginationMode: 'traditional' | 'infinite';
  goToPage: (pageIndex: number) => void;
  nextPage: () => void;
  previousPage: () => void;
  setPageSize: (size: number) => void;
  updatePaginationMeta: (meta: PaginationMeta) => void;
  setPaginationMode: (mode: 'traditional' | 'infinite') => void;
  canGoNext: boolean;
  canGoPrevious: boolean;
}

const PaginationContext = createContext<PaginationContextType | undefined>(
  undefined
);

export function PaginationProvider({
  children,
}: {
  children: React.ReactNode;
}) {
  const [pageIndex, setPageIndex] = useState(1);
  const [pageSize, setPageSizeState] = useState(10);
  const [pageCount, setPageCount] = useState(1);
  const [totalData, setTotalData] = useState(0);
  const [paginationMode, setPaginationModeState] = useState<'traditional' | 'infinite'>(
    'traditional'
  );

  const goToPage = useCallback((newPageIndex: number) => {
    setPageIndex(Math.max(1, newPageIndex));
  }, []);

  const nextPage = useCallback(() => {
    setPageIndex((prev) => Math.min(prev + 1, pageCount));
  }, [pageCount]);

  const previousPage = useCallback(() => {
    setPageIndex((prev) => Math.max(prev - 1, 1));
  }, []);

  const setPageSizeFn = useCallback((size: number) => {
    setPageSizeState(size);
    setPageIndex(1);
  }, []);

  const updatePaginationMeta = useCallback((meta: PaginationMeta) => {
    setPageIndex(meta.pageIndex);
    setPageSizeState(meta.pageSize);
    setPageCount(meta.pageCount);
    setTotalData(meta.totalData);
  }, []);

  const setPaginationMode = useCallback(
    (mode: 'traditional' | 'infinite') => {
      setPaginationModeState(mode);
    },
    []
  );

  const canGoNext = pageIndex < pageCount;
  const canGoPrevious = pageIndex > 1;

  const value: PaginationContextType = {
    pageIndex,
    pageSize,
    pageCount,
    totalData,
    paginationMode,
    goToPage,
    nextPage,
    previousPage,
    setPageSize: setPageSizeFn,
    updatePaginationMeta,
    setPaginationMode,
    canGoNext,
    canGoPrevious,
  };

  return (
    <PaginationContext.Provider value={value}>
      {children}
    </PaginationContext.Provider>
  );
}

export function usePagination(): PaginationContextType {
  const context = useContext(PaginationContext);
  if (!context) {
    throw new Error(
      'usePagination must be used within a PaginationProvider'
    );
  }
  return context;
}

'use client';

import React, { createContext, useContext, useState, useCallback } from 'react';
import { RowSelectionState, ExpandedRowState } from '@/lib/data-table/types';

interface SelectionContextType {
  rowSelection: RowSelectionState;
  expandedRows: ExpandedRowState;
  toggleRow: (rowId: string) => void;
  toggleAll: (rowIds: string[], selected: boolean) => void;
  selectRows: (rowIds: string[]) => void;
  deselectRows: (rowIds: string[]) => void;
  clearSelection: () => void;
  isRowSelected: (rowId: string) => boolean;
  selectedCount: number;
  toggleExpanded: (rowId: string) => void;
  isRowExpanded: (rowId: string) => boolean;
  expandedCount: number;
  getSelectedRowIds: () => string[];
}

const SelectionContext = createContext<SelectionContextType | undefined>(
  undefined
);

export function SelectionProvider({
  children,
}: {
  children: React.ReactNode;
}) {
  const [rowSelection, setRowSelection] = useState<RowSelectionState>({});
  const [expandedRows, setExpandedRows] = useState<ExpandedRowState>({});

  const toggleRow = useCallback((rowId: string) => {
    setRowSelection((prev) => ({
      ...prev,
      [rowId]: !prev[rowId],
    }));
  }, []);

  const toggleAll = useCallback((rowIds: string[], selected: boolean) => {
    const newSelection: RowSelectionState = {};
    rowIds.forEach((id) => {
      newSelection[id] = selected;
    });
    setRowSelection(selected ? newSelection : {});
  }, []);

  const selectRows = useCallback((rowIds: string[]) => {
    setRowSelection((prev) => {
      const newSelection = { ...prev };
      rowIds.forEach((id) => {
        newSelection[id] = true;
      });
      return newSelection;
    });
  }, []);

  const deselectRows = useCallback((rowIds: string[]) => {
    setRowSelection((prev) => {
      const newSelection = { ...prev };
      rowIds.forEach((id) => {
        delete newSelection[id];
      });
      return newSelection;
    });
  }, []);

  const clearSelection = useCallback(() => {
    setRowSelection({});
  }, []);

  const isRowSelected = useCallback(
    (rowId: string) => !!rowSelection[rowId],
    [rowSelection]
  );

  const selectedCount = Object.values(rowSelection).filter(Boolean).length;

  const toggleExpanded = useCallback((rowId: string) => {
    setExpandedRows((prev) => ({
      ...prev,
      [rowId]: !prev[rowId],
    }));
  }, []);

  const isRowExpanded = useCallback(
    (rowId: string) => !!expandedRows[rowId],
    [expandedRows]
  );

  const expandedCount = Object.values(expandedRows).filter(Boolean).length;

  const getSelectedRowIds = useCallback(
    () => Object.keys(rowSelection).filter((id) => rowSelection[id]),
    [rowSelection]
  );

  const value: SelectionContextType = {
    rowSelection,
    expandedRows,
    toggleRow,
    toggleAll,
    selectRows,
    deselectRows,
    clearSelection,
    isRowSelected,
    selectedCount,
    toggleExpanded,
    isRowExpanded,
    expandedCount,
    getSelectedRowIds,
  };

  return (
    <SelectionContext.Provider value={value}>
      {children}
    </SelectionContext.Provider>
  );
}

export function useSelection(): SelectionContextType {
  const context = useContext(SelectionContext);
  if (!context) {
    throw new Error(
      'useSelection must be used within a SelectionProvider'
    );
  }
  return context;
}

'use client';

import React, { createContext, useContext, useState, useCallback } from 'react';
import { SortState, SortOrder } from '@/lib/data-table/types';

interface SortContextType {
  sort: SortState;
  setSort: (column: string | null, order?: SortOrder) => void;
  toggleSort: (column: string) => void;
  clearSort: () => void;
  isSorted: (column: string) => boolean;
  getSortOrder: (column: string) => SortOrder;
}

const SortContext = createContext<SortContextType | undefined>(undefined);

export function SortProvider({ children }: { children: React.ReactNode }) {
  const [sort, setSort] = useState<SortState>({
    column: null,
    order: null,
  });

  const setSortFn = useCallback((column: string | null, order: SortOrder = 'asc') => {
    setSort({
      column,
      order: column ? order : null,
    });
  }, []);

  const toggleSort = useCallback((column: string) => {
    setSort((prev) => {
      if (prev.column === column) {
        // Cycle: asc -> desc -> null
        if (prev.order === 'asc') {
          return { column, order: 'desc' };
        } else if (prev.order === 'desc') {
          return { column: null, order: null };
        } else {
          return { column, order: 'asc' };
        }
      } else {
        return { column, order: 'asc' };
      }
    });
  }, []);

  const clearSort = useCallback(() => {
    setSort({ column: null, order: null });
  }, []);

  const isSorted = useCallback(
    (column: string) => sort.column === column && sort.order !== null,
    [sort]
  );

  const getSortOrder = useCallback(
    (column: string) => (sort.column === column ? sort.order : null),
    [sort]
  );

  const value: SortContextType = {
    sort,
    setSort: setSortFn,
    toggleSort,
    clearSort,
    isSorted,
    getSortOrder,
  };

  return (
    <SortContext.Provider value={value}>{children}</SortContext.Provider>
  );
}

export function useSort(): SortContextType {
  const context = useContext(SortContext);
  if (!context) {
    throw new Error('useSort must be used within a SortProvider');
  }
  return context;
}

