            key={column.id}
            field={column.id}
            label={column.label}
          />
        );

      case 'dateRange':
        return (
          <DateRangeFilter
            key={column.id}
            field={column.id}
            label={column.label}
          />
        );

      case 'select':
        return (
          <SelectFilter
            key={column.id}
            field={column.id}
            label={column.label}
            options={column.options || []}
            placeholder={column.placeholder}
          />
        );

      case 'multiSelect':
        return (
          <MultiSelectFilter
            key={column.id}
            field={column.id}
            label={column.label}
            options={column.options || []}
