'use client';

import React, { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import { useFilters } from '../contexts/FilterContext';
import { FilterOption } from '@/lib/data-table/types';
import { ChevronDown } from 'lucide-react';

interface MultiSelectFilterProps {
  field: string;
  label: string;
  options: FilterOption[];
  placeholder?: string;
}

export function MultiSelectFilter({
  field,
  label,
  options,
  placeholder = 'Select options...',
}: MultiSelectFilterProps) {
  const { filters, addFilter, removeFilter } = useFilters();
  const [isOpen, setIsOpen] = useState(false);

  const existingFilter = filters.find(
    (f) => f.field === field && f.type === 'multiSelect'
  );

  const [selectedValues, setSelectedValues] = useState<string[]>(
    existingFilter ? (existingFilter.value as string[]) : []
  );

  // Sync local state when filter is cleared externally
  // Use a stable string key so this doesn't fire on every render
  const existingValueKey = existingFilter ? JSON.stringify(existingFilter.value) : null;
  useEffect(() => {
    if (!existingFilter) {
      setSelectedValues([]);
    } else {
      setSelectedValues(existingFilter.value as string[]);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [existingValueKey]);

  const handleToggle = (value: string) => {
    const newValues = selectedValues.includes(String(value))
      ? selectedValues.filter((v) => v !== String(value))
      : [...selectedValues, String(value)];

    setSelectedValues(newValues);
    removeFilter(field);

    if (newValues.length > 0) {
      addFilter({
        field,
        operator: 'in',
        value: newValues,
        type: 'multiSelect',
      });
    }
  };

  const handleClear = () => {
    setSelectedValues([]);
    removeFilter(field);
  };

  const getSelectedLabels = () => {
    return options
      .filter((opt) => selectedValues.includes(String(opt.value)))
      .map((opt) => opt.label);
  };

  return (
    <div className="space-y-2">
      <label className="text-sm font-medium">{label}</label>
      <div className="relative">
        <Button
          variant="outline"
          role="combobox"
          className="w-full justify-between"
          onClick={() => setIsOpen(!isOpen)}
        >
          <span className="truncate">
            {selectedValues.length > 0
              ? `${selectedValues.length} selected`
              : placeholder}
          </span>
          <ChevronDown className="h-4 w-4 opacity-50" />
        </Button>

        {isOpen && (
          <div className="absolute top-full left-0 right-0 mt-1 border border-input rounded-md bg-background shadow-md z-50">
            <div className="p-2 space-y-2 max-h-48 overflow-y-auto">
              {options.map((option) => (
                <div key={option.value} className="flex items-center space-x-2">
                  <Checkbox
                    id={`${field}-${option.value}`}
                    checked={selectedValues.includes(String(option.value))}
                    onCheckedChange={() => handleToggle(String(option.value))}
                  />
                  <label
                    htmlFor={`${field}-${option.value}`}
                    className="text-sm cursor-pointer flex-1"
                  >
                    {option.label}
                  </label>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {selectedValues.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {getSelectedLabels().map((label) => (
            <Badge key={label} variant="secondary">
              {label}
            </Badge>
          ))}
          <Button
            variant="ghost"
            size="sm"
            onClick={handleClear}
            className="h-6 px-2 text-xs"
          >
            Clear
          </Button>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { useFilters } from '../contexts/FilterContext';

interface RangeFilterProps {
  field: string;
  label: string;
  min?: number;
  max?: number;
  step?: number;
}

export function RangeFilter({
  field,
  label,
  min = 0,
  max = 100,
  step = 1,
}: RangeFilterProps) {
  const { filters, addFilter, removeFilter } = useFilters();

  const existingFilter = filters.find(
    (f) => f.field === field && f.type === 'range'
  );

  const existingRange = existingFilter?.value as [number, number] | undefined;

  const [minValue, setMinValue] = useState<number>(existingRange ? existingRange[0] : min);
  const [maxValue, setMaxValue] = useState<number>(existingRange ? existingRange[1] : max);

  // Use a stable string key to avoid firing on every re-render
  const existingValueKey = existingFilter ? JSON.stringify(existingFilter.value) : null;

  // Sync local state only when the actual filter value changes (not every render)
  useEffect(() => {
    if (!existingFilter) {
      setMinValue(min);
      setMaxValue(max);
    } else if (existingFilter.value) {
      const [eMin, eMax] = existingFilter.value as [number, number];
      setMinValue(eMin);
      setMaxValue(eMax);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [existingValueKey, min, max]);

  const handleApply = () => {
    removeFilter(field);
    if (minValue < maxValue) {
      addFilter({
        field,
        operator: 'between',
        value: [minValue, maxValue],
        type: 'range',
      });
    }
  };

  const handleClear = () => {
    setMinValue(min);
    setMaxValue(max);
    removeFilter(field);
  };

  return (
    <div className="space-y-3">
      <label className="text-sm font-medium">{label}</label>
      <div className="space-y-2">
        <div className="flex gap-2">
          <div className="flex-1">
            <label className="text-xs text-muted-foreground">Min</label>
            <Input
              type="number"
              min={min}
              max={maxValue - step}
              step={step}
              value={minValue}
              onChange={(e) => setMinValue(Number(e.target.value))}
              className="h-8"
            />
          </div>
          <div className="flex-1">
            <label className="text-xs text-muted-foreground">Max</label>
            <Input
              type="number"
              min={minValue + step}
              max={max}
              step={step}
              value={maxValue}
              onChange={(e) => setMaxValue(Number(e.target.value))}
              className="h-8"
            />
          </div>
        </div>
        <div className="text-xs text-muted-foreground">
          Range: {minValue} - {maxValue}
        </div>
        <div className="flex gap-2">
          <Button size="sm" variant="default" onClick={handleApply}>
            Apply
          </Button>
          {existingFilter && (
            <Button size="sm" variant="outline" onClick={handleClear}>
              Clear
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useCallback, useEffect } from 'react';
import { Input } from '@/components/ui/input';
import { X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useFilters } from '../contexts/FilterContext';
import { FilterValue } from '@/lib/data-table/types';

interface SearchFilterProps {
  field: string;
  label: string;
  placeholder?: string;
}

export function SearchFilter({
  field,
  label,
  placeholder = 'Search...',
}: SearchFilterProps) {
  const { filters, addFilter, removeFilter } = useFilters();

  const existingFilter = filters.find(
    (f) => f.field === field && f.type === 'search'
  );

  // Initialize from context so value persists when popover is closed & reopened
  const [value, setValue] = useState<string>(
    existingFilter ? String(existingFilter.value) : ''
  );

  // Sync local state if filter is cleared externally (e.g. "Reset All")
  // Use existingFilter?.value (primitive) not the full object to avoid firing every render
  useEffect(() => {
    if (!existingFilter) {
      setValue('');
    } else {
      setValue(String(existingFilter.value));
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [existingFilter?.value]);

  const handleChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const newValue = e.target.value;
      setValue(newValue);

      if (newValue.trim()) {
        if (existingFilter) {
          removeFilter(field);
        }
        addFilter({
          field,
          operator: 'contains',
          value: newValue,
          type: 'search',
        });
      } else {
        if (existingFilter) {
          removeFilter(field);
        }
      }
    },
    [field, existingFilter, addFilter, removeFilter]
  );

  const handleClear = useCallback(() => {
    setValue('');
    removeFilter(field);
  }, [field, removeFilter]);

  return (
    <div className="space-y-2">
      <label className="text-sm font-medium">{label}</label>
      <div className="relative">
        <Input
          placeholder={placeholder}
          value={value}
          onChange={handleChange}
          className="pr-8"
        />
        {value && (
          <Button
            variant="ghost"
            size="sm"
            onClick={handleClear}
            className="absolute right-1 top-1/2 -translate-y-1/2 h-6 w-6 p-0"
          >
            <X className="h-4 w-4" />
          </Button>
        )}
      </div>
    </div>
  );
}

